-- Re-runnable seed. Existing dish rows are preserved; IDs 1-9 are reserved.
SET NAMES utf8mb4;
SET time_zone = '+08:00';
SELECT CURRENT_DATE(),id FROM dishes WHERE active = TRUE AND id BETWEEN 1 AND 9
AND NOT EXISTS (SELECT 1 FROM daily_menu_items WHERE menu_date=CURRENT_DATE())
ON DUPLICATE KEY UPDATE dish_id = daily_menu_items.dish_id;
SELECT CURRENT_DATE() + INTERVAL 1 DAY,id FROM dishes WHERE active = TRUE AND id BETWEEN 1 AND 9
AND NOT EXISTS (SELECT 1 FROM daily_menu_items WHERE menu_date=CURRENT_DATE() + INTERVAL 1 DAY)
ON DUPLICATE KEY UPDATE dish_id = daily_menu_items.dish_id;
